header='''---
theme: default
title: Please improve yourself · Pending, Inc.
author: Anish Shah
info: Build, instrument, evaluate and improve an agent in your own Forge project.
class: cover
aspectRatio: 16/9
canvasWidth: 1280
colorSchema: light
transition: fade
fonts:
  sans: IBM Plex Sans
  mono: IBM Plex Mono
  provider: none
mdc: true
highlighter: shiki
lineNumbers: false
drawings:
  enabled: false
exportFilename: pending-inc
---
'''
ids={s['key']:i+1 for i,s in enumerate(S)}
parts=[]
for i,s in enumerate(S):
    body=re.sub(r'(<table[^>]*>)', r'\1<tbody>', s['body']).replace('</table>', '</tbody></table>')
    if s['key']=='native-results':
        body=re.sub(r'<a href="([^"]+)" class="capture-frame".*?</a>',r'<a class="capture-link" href="\1"><CaptureDetail src="/images/visual-v030-pending-comparison.png" :x="80" :y="305" :width="1180" :height="380" label="Four saved W&B Table case rows, scores and execution evidence" /></a>',body)
    body=re.sub(r'(<div class="bottom-note"[^>]*>)(.*?)(</div>)',lambda m:m.group(1)+re.sub(r'`([^`]+)`',r'<code>\1</code>',m.group(2))+m.group(3),body)
    for key,n in ids.items():
        body=body.replace('](#'+key+')',f']({BASE}/{n})').replace('href="#'+key+'"',f'href="{BASE}/{n}"')
    if s['cls']=='answer': body=re.sub(r'\[([^]]*(?:Return|Continue)[^]]*)\]\(([^)]+)\)',r'<span class="source-link"><a href="\2">\1</a></span>',body)
    content=f'# {s["title"]}\n\n{body}\n\n<!--\n{s["notes"]}\n-->\n'
    if i: content=('---\n'+('class: '+s['cls']+'\n' if s['cls'] else '')+'---\n\n')+content
    parts.append(content)
(ROOT/'slides.md').write_text(header+'\n'.join(parts))
(ROOT/'notes/facilitator-notes.md').write_text('# Pending, Inc. presenter notes\n\n'+ '\n\n'.join(f'## {i+1}. {s["title"].replace("<br>"," ")}\n\n{s["notes"]}' for i,s in enumerate(S))+'\n')
(ROOT/'notes/slide-map.json').write_text(json.dumps({'total_slides':len(S),'main_slides':ids['answer-tool']-1,'slides':[{'number':i+1,'key':s['key'],'title':s['title'],'kind':s['cls'] or 'explanation','notes':s['notes'],'answer': next((ids[key] for key in ids if key.startswith('answer-') and ('#'+key+'\"') in s['body']),None)} for i,s in enumerate(S)]},indent=2)+'\n')
print(f'Wrote {len(S)} slides')
